//! CPU voice latency harness for the VR assistant (`vox`): STT and TTS through the sherpa-onnx C API, loaded at run time.
//!
//! * [`wav`] / [`resample`]: audio file I/O and a Kaiser-windowed polyphase resampler (shared with the production `vox`).
//! * [`sherpa`]: safe wrappers over the C API (`dlopen` of `libsherpa-onnx-c-api.so`, so building needs no native libraries).
//! * [`bench`]: the measurements (latency, time to first audio, CPU use); [`stats`], [`text`]: helpers.
//!
//! `ffi.rs` is generated by bindgen from `sherpa-onnx/c-api/c-api.h` (1.13.8); the layout tests it contains guard the struct
//! layouts. Regeneration recipe: `analysis/overnight/desk.md`.
#![deny(unsafe_code)]

pub mod bench;
#[allow(unsafe_code)]
pub mod ffi;
pub mod resample;
#[allow(unsafe_code)]
pub mod sherpa;
pub mod stats;
pub mod text;
pub mod wav;
